def icon(name):return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+ICONS.get('api' if name=='api-docs' else name,ICONS['forge'])+'"/></svg>'
def button(text,url,secondary=False):return '<a class="button '+('secondary' if secondary else 'gold')+'" href="'+url+'">'+text+icon('arrow')+'</a>'
def heading(kicker,title,description):return f'<header class="page-heading"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p>{description}</p></header>'
def panel(title,body,link='',extra=''):
 return f'<section class="panel {extra}"><div class="panel-heading"><h2>{title}</h2>{link}</div>{body}</section>'
def table(headers,id,caption='Loading live pool records…'):
 return '<div class="table-scroll"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in headers)+'</tr></thead><tbody id="'+id+'"><tr><td colspan="'+str(len(headers))+'" class="empty">'+caption+'</td></tr></tbody></table></div>'
def metrics(items):return '<div class="metric-grid">'+''.join(f'<article class="metric"><span>{label}</span><strong data-metric="{key}">—</strong><small>{note}</small></article>' for label,key,note in items)+'</div>'
def lookup(id='lookup',label='Your mining address',placeholder='0x… your RGN receiving address'):
 return f'<form class="lookup" id="{id}"><label for="{id}-address">{label}</label><div class="input-action"><input id="{id}-address" name="address" autocomplete="off" spellcheck="false" placeholder="{placeholder}" pattern="0x[0-9a-fA-F]{{40}}" required aria-describedby="{id}-error"><button class="button gold" type="submit">View miner {icon("arrow")}</button></div><p class="form-error" id="{id}-error" role="status"></p></form>'

